  "transactiondate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "transactiontype" CHAR(1) NOT NULL,
  "quantity" INTEGER NOT NULL,
  "actualcost" DECIMAL(19,4) NOT NULL,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "fk_transactionhistory_product_productid" FOREIGN KEY ("productid") REFERENCES "production_product" ("productid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_transactionhistory_transactiontype" CHECK ((upper("transactiontype") in ('W','S','P')))
);

CREATE TABLE "production_transactionhistoryarchive" (
  "transactionid" INTEGER NOT NULL,
  "productid" INTEGER NOT NULL,
  "referenceorderid" INTEGER NOT NULL,
  "referenceorderlineid" INTEGER NOT NULL DEFAULT 0,
  "transactiondate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "transactiontype" CHAR(1) NOT NULL,
  "quantity" INTEGER NOT NULL,
  "actualcost" DECIMAL(19,4) NOT NULL,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("transactionid"),
  CONSTRAINT "ck_transactionhistoryarchive_transactiontype" CHECK ((upper("transactiontype") in ('W','S','P')))
);

CREATE TABLE "production_workorder" (
  "workorderid" INTEGER PRIMARY KEY,
  "productid" INTEGER NOT NULL,
  "orderqty" INTEGER NOT NULL,
  "stockedqty" DECIMAL(38,6) GENERATED ALWAYS AS (coalesce(("orderqty" - "scrappedqty"),0)) STORED,
  "scrappedqty" SMALLINT NOT NULL,
  "startdate" DATETIME NOT NULL,
  "enddate" DATETIME,
  "duedate" DATETIME NOT NULL,
  "scrapreasonid" SMALLINT,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "fk_workorder_product_productid" FOREIGN KEY ("productid") REFERENCES "production_product" ("productid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_workorder_scrapreason_scrapreasonid" FOREIGN KEY ("scrapreasonid") REFERENCES "production_scrapreason" ("scrapreasonid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_workorder_enddate" CHECK ((("enddate" >= "startdate") or ("enddate" is null))),
  CONSTRAINT "ck_workorder_orderqty" CHECK (("orderqty" > 0)),
  CONSTRAINT "ck_workorder_scrappedqty" CHECK (("scrappedqty" >= 0))
);

CREATE TABLE "production_workorderrouting" (
  "workorderid" INTEGER NOT NULL,
  "productid" INTEGER NOT NULL,
  "operationsequence" SMALLINT NOT NULL,
  "locationid" SMALLINT NOT NULL,
  "scheduledstartdate" DATETIME NOT NULL,
  "scheduledenddate" DATETIME NOT NULL,
  "actualstartdate" DATETIME,
  "actualenddate" DATETIME,
  "actualresourcehrs" DECIMAL(9,4),
  "plannedcost" DECIMAL(19,4) NOT NULL,
  "actualcost" DECIMAL(19,4),
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("workorderid", "productid", "operationsequence"),
  CONSTRAINT "fk_workorderrouting_location_locationid" FOREIGN KEY ("locationid") REFERENCES "production_location" ("locationid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_workorderrouting_workorder_workorderid" FOREIGN KEY ("workorderid") REFERENCES "production_workorder" ("workorderid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_workorderrouting_actualcost" CHECK (("actualcost" > 0.00)),
  CONSTRAINT "ck_workorderrouting_actualenddate" CHECK ((("actualenddate" >= "actualstartdate") or ("actualenddate" is null) or ("actualstartdate" is null))),
  CONSTRAINT "ck_workorderrouting_actualresourcehrs" CHECK (("actualresourcehrs" >= 0.0000)),
  CONSTRAINT "ck_workorderrouting_plannedcost" CHECK (("plannedcost" > 0.00)),
  CONSTRAINT "ck_workorderrouting_scheduledenddate" CHECK (("scheduledenddate" >= "scheduledstartdate"))
);

CREATE TABLE "purchasing_vendor" (
  "businessentityid" INTEGER NOT NULL,
  "accountnumber" VARCHAR(15) NOT NULL,
  "name" VARCHAR(50) NOT NULL,
  "creditrating" TINYINT NOT NULL,
  "preferredvendorstatus" TINYINT NOT NULL DEFAULT 1,
  "activeflag" TINYINT NOT NULL DEFAULT 1,
  "purchasingwebserviceurl" VARCHAR(1024),
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("businessentityid"),
  CONSTRAINT "fk_vendor_businessentity_businessentityid" FOREIGN KEY ("businessentityid") REFERENCES "person_businessentity" ("businessentityid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_vendor_creditrating" CHECK (("creditrating" between 1 and 5))
);

CREATE TABLE "purchasing_productvendor" (
  "productid" INTEGER NOT NULL,
  "businessentityid" INTEGER NOT NULL,
  "averageleadtime" INTEGER NOT NULL,
  "standardprice" DECIMAL(19,4) NOT NULL,
  "lastreceiptcost" DECIMAL(19,4),
  "lastreceiptdate" DATETIME,
  "minorderqty" INTEGER NOT NULL,
  "maxorderqty" INTEGER NOT NULL,
  "onorderqty" INTEGER,
  "unitmeasurecode" CHAR(3) NOT NULL,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("productid", "businessentityid"),
  CONSTRAINT "fk_productvendor_product_productid" FOREIGN KEY ("productid") REFERENCES "production_product" ("productid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_productvendor_unitmeasure_unitmeasurecode" FOREIGN KEY ("unitmeasurecode") REFERENCES "production_unitmeasure" ("unitmeasurecode") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_productvendor_vendor_businessentityid" FOREIGN KEY ("businessentityid") REFERENCES "purchasing_vendor" ("businessentityid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_productvendor_averageleadtime" CHECK (("averageleadtime" >= 1)),
  CONSTRAINT "ck_productvendor_lastreceiptcost" CHECK (("lastreceiptcost" > 0.00)),
  CONSTRAINT "ck_productvendor_maxorderqty" CHECK (("maxorderqty" >= 1)),
  CONSTRAINT "ck_productvendor_minorderqty" CHECK (("minorderqty" >= 1)),
  CONSTRAINT "ck_productvendor_onorderqty" CHECK (("onorderqty" >= 0)),
  CONSTRAINT "ck_productvendor_standardprice" CHECK (("standardprice" > 0.00))
);

CREATE TABLE "purchasing_shipmethod" (
  "shipmethodid" INTEGER PRIMARY KEY,
  "name" VARCHAR(50) NOT NULL,
  "shipbase" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "shiprate" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "rowguid" CHAR(36) NOT NULL,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ck_shipmethod_shipbase" CHECK (("shipbase" > 0.00)),
  CONSTRAINT "ck_shipmethod_shiprate" CHECK (("shiprate" > 0.00))
);

CREATE TABLE "purchasing_purchaseorderheader" (
  "purchaseorderid" INTEGER PRIMARY KEY,
  "revisionnumber" TINYINT NOT NULL DEFAULT 0,
  "status" TINYINT NOT NULL DEFAULT 1,
  "employeeid" INTEGER NOT NULL,
  "vendorid" INTEGER NOT NULL,
  "shipmethodid" INTEGER NOT NULL,
  "orderdate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "shipdate" DATETIME,
  "subtotal" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "taxamt" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "freight" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "totaldue" DECIMAL(19,4) GENERATED ALWAYS AS (coalesce((("subtotal" + "taxamt") + "freight"),0)) STORED NOT NULL,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "fk_purchaseorderheader_employee_employeeid" FOREIGN KEY ("employeeid") REFERENCES "humanresources_employee" ("businessentityid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_purchaseorderheader_shipmethod_shipmethodid" FOREIGN KEY ("shipmethodid") REFERENCES "purchasing_shipmethod" ("shipmethodid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_purchaseorderheader_vendor_vendorid" FOREIGN KEY ("vendorid") REFERENCES "purchasing_vendor" ("businessentityid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_purchaseorderheader_freight" CHECK (("freight" >= 0.00)),
  CONSTRAINT "ck_purchaseorderheader_shipdate" CHECK ((("shipdate" >= "orderdate") or ("shipdate" is null))),
  CONSTRAINT "ck_purchaseorderheader_status" CHECK (("status" between 1 and 4)),
  CONSTRAINT "ck_purchaseorderheader_subtotal" CHECK (("subtotal" >= 0.00)),
  CONSTRAINT "ck_purchaseorderheader_taxamt" CHECK (("taxamt" >= 0.00))
);

CREATE TABLE "purchasing_purchaseorderdetail" (
  "purchaseorderid" INTEGER NOT NULL,
  "purchaseorderdetailid" INTEGER NOT NULL,
  "duedate" DATETIME NOT NULL,
  "orderqty" SMALLINT NOT NULL,
  "productid" INTEGER NOT NULL,
  "unitprice" DECIMAL(19,4) NOT NULL,
  "linetotal" DECIMAL(38,6) GENERATED ALWAYS AS (coalesce(("orderqty" * "unitprice"),0.00)) STORED,
  "receivedqty" DECIMAL(8,2) NOT NULL,
  "rejectedqty" DECIMAL(8,2) NOT NULL,
  "stockedqty" DECIMAL(38,6) GENERATED ALWAYS AS (coalesce(("receivedqty" - "rejectedqty"),0.00)) STORED,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("purchaseorderid", "purchaseorderdetailid"),
  CONSTRAINT "fk_purchaseorderdetail_product_productid" FOREIGN KEY ("productid") REFERENCES "production_product" ("productid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_purchaseorderdetail_purchaseorderheader_purchaseorderid" FOREIGN KEY ("purchaseorderid") REFERENCES "purchasing_purchaseorderheader" ("purchaseorderid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_purchaseorderdetail_orderqty" CHECK (("orderqty" > 0)),
  CONSTRAINT "ck_purchaseorderdetail_receivedqty" CHECK (("receivedqty" >= 0.00)),
  CONSTRAINT "ck_purchaseorderdetail_rejectedqty" CHECK (("rejectedqty" >= 0.00)),
  CONSTRAINT "ck_purchaseorderdetail_unitprice" CHECK (("unitprice" >= 0.00))
);

