  CONSTRAINT "fk_customer_salesterritory_territoryid" FOREIGN KEY ("territoryid") REFERENCES "sales_salesterritory" ("territoryid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_customer_store_storeid" FOREIGN KEY ("storeid") REFERENCES "sales_store" ("businessentityid") ON UPDATE NO ACTION ON DELETE NO ACTION
