);

CREATE TABLE "sales_salesorderheader" (
  "salesorderid" INTEGER PRIMARY KEY,
  "revisionnumber" TINYINT NOT NULL DEFAULT 0,
  "orderdate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "duedate" DATETIME NOT NULL,
  "shipdate" DATETIME,
  "status" TINYINT NOT NULL DEFAULT 1,
  "onlineorderflag" TINYINT NOT NULL DEFAULT 1,
  "salesordernumber" VARCHAR(25),
  "purchaseordernumber" VARCHAR(25),
  "accountnumber" VARCHAR(15),
  "customerid" INTEGER NOT NULL,
  "salespersonid" INTEGER,
  "territoryid" INTEGER,
  "billtoaddressid" INTEGER NOT NULL,
  "shiptoaddressid" INTEGER NOT NULL,
  "shipmethodid" INTEGER NOT NULL,
  "creditcardid" INTEGER,
  "creditcardapprovalcode" VARCHAR(15),
  "currencyrateid" INTEGER,
  "subtotal" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "taxamt" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "freight" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "totaldue" DECIMAL(19,4) GENERATED ALWAYS AS (coalesce((("subtotal" + "taxamt") + "freight"),0)) STORED,
  "comment" VARCHAR(128),
  "rowguid" CHAR(36) NOT NULL,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "fk_salesorderheader_address_billtoaddressid" FOREIGN KEY ("billtoaddressid") REFERENCES "person_address" ("addressid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_salesorderheader_address_shiptoaddressid" FOREIGN KEY ("shiptoaddressid") REFERENCES "person_address" ("addressid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_salesorderheader_creditcard_creditcardid" FOREIGN KEY ("creditcardid") REFERENCES "sales_creditcard" ("creditcardid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_salesorderheader_currencyrate_currencyrateid" FOREIGN KEY ("currencyrateid") REFERENCES "sales_currencyrate" ("currencyrateid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_salesorderheader_customer_customerid" FOREIGN KEY ("customerid") REFERENCES "sales_customer" ("customerid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_salesorderheader_salesperson_salespersonid" FOREIGN KEY ("salespersonid") REFERENCES "sales_salesperson" ("businessentityid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_salesorderheader_salesterritory_territoryid" FOREIGN KEY ("territoryid") REFERENCES "sales_salesterritory" ("territoryid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_salesorderheader_shipmethod_shipmethodid" FOREIGN KEY ("shipmethodid") REFERENCES "purchasing_shipmethod" ("shipmethodid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_salesorderheader_duedate" CHECK (("duedate" >= "orderdate")),
  CONSTRAINT "ck_salesorderheader_freight" CHECK (("freight" >= 0.00)),
  CONSTRAINT "ck_salesorderheader_shipdate" CHECK ((("shipdate" >= "orderdate") or ("shipdate" is null))),
  CONSTRAINT "ck_salesorderheader_status" CHECK (("status" between 0 and 8)),
  CONSTRAINT "ck_salesorderheader_subtotal" CHECK (("subtotal" >= 0.00)),
  CONSTRAINT "ck_salesorderheader_taxamt" CHECK (("taxamt" >= 0.00))
);

