  PRIMARY KEY ("specialofferid", "productid"),
  CONSTRAINT "fk_specialofferproduct_product_productid" FOREIGN KEY ("productid") REFERENCES "production_product" ("productid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "fk_specialofferproduct_specialoffer_specialofferid" FOREIGN KEY ("specialofferid") REFERENCES "sales_specialoffer" ("specialofferid") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "sales_salesorderdetail" (
  "salesorderid" INTEGER NOT NULL,
  "salesorderdetailid" INTEGER NOT NULL,
  "carriertrackingnumber" VARCHAR(25),
  "orderqty" SMALLINT NOT NULL,
  "productid" INTEGER NOT NULL,
  "specialofferid" INTEGER NOT NULL,
  "unitprice" DECIMAL(19,4) NOT NULL,
  "unitpricediscount" DECIMAL(19,4) NOT NULL DEFAULT 0.0000,
  "linetotal" DECIMAL(38,6) GENERATED ALWAYS AS (coalesce((("unitprice" * (1.0 - "unitpricediscount")) * "orderqty"),0.0)) STORED,
  "rowguid" CHAR(36) NOT NULL,
  "modifieddate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("salesorderid", "salesorderdetailid"),
  CONSTRAINT "fk_salesorderdetail_salesorderheader_salesorderid" FOREIGN KEY ("salesorderid") REFERENCES "sales_salesorderheader" ("salesorderid") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "fk_salesorderdetail_specialofferproduct_specialofferidproductid" FOREIGN KEY ("specialofferid", "productid") REFERENCES "sales_specialofferproduct" ("specialofferid", "productid") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "ck_salesorderdetail_orderqty" CHECK (("orderqty" > 0)),
  CONSTRAINT "ck_salesorderdetail_unitprice" CHECK (("unitprice" >= 0.00)),
  CONSTRAINT "ck_salesorderdetail_unitpricediscount" CHECK (("unitpricediscount" >= 0.00))
);

CREATE TABLE "sales_salesreason" (
  "salesreasonid" INTEGER PRIMARY KEY,
