  CONSTRAINT "fk_salesorderheadersalesreason_salesreason_salesreasonid" FOREIGN KEY ("salesreasonid") REFERENCES "sales_salesreason" ("salesreasonid") ON UPDATE NO ACTION ON DELETE NO ACTION
);

